#include <stdio.h>
#include <stdlib.h>
typedef struct { long long n, d; } Rational;
long long gcd(long long a, long long b) {
    while (b) { long long r=a%b; a=b; b=r; }
    return a;
}
Rational make(long long n, long long d) {
    if (!d) { fputs("Zero denominator\n", stderr); exit(1); }
    if (d<0) { n=-n; d=-d; }
    long long g=gcd(n<0 ? -n : n, d);
    return (Rational){n/g,d/g};
}
Rational add(Rational a, Rational b) {
    return make(a.n*b.d+b.n*a.d, a.d*b.d);
}
Rational multiply(Rational a, Rational b) {
    return make(a.n*b.n, a.d*b.d);
}
int equal(Rational a, Rational b) {
    return a.n==b.n && a.d==b.d;
}
int main(void) {
    Rational a=make(1,2), b=make(1,3);
    Rational c=add(a,b), d=multiply(a,b);
    printf("Sum=%lld/%lld\n",c.n,c.d);
    printf("Product=%lld/%lld\n",d.n,d.d);
    printf("Equal=%d\n",equal(a,make(2,4)));
    return 0;
}

rational.text:
Rational-number ADT in C
Understand the idea
A rational number is a fraction with an integer numerator and a nonzero integer denominator.
An ADT stores it and defines operations on it.


ADT and invariant
A rational number is n/d with integer n and nonzero d.
Store a reduced numerator and positive denominator.
This makes equality a direct comparison of the two fields.
All values enter through make().


